import{_ as s,a0 as i,w as u,s as l,I as p,x as o,a1 as e,A as r,ao as b}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"在Ubuntu中將Dropbox文件夾放移動硬盤上 | LCTT x X-CMD","titleTemplate":false,"description":"在Ubuntu中將Dropbox文件夾放移動硬盤上 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Ubuntu中將Dropbox文件夾放移動硬盤上 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Ubuntu中將Dropbox文件夾放移動硬盤上 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/Move Dropbox’s Folder To An External Drive In Ubuntu","title":"在Ubuntu中將Dropbox文件夾放移動硬盤上","tag":"201401","desc":""},"relativePath":"201401/Move Dropbox’s Folder To An External Drive In Ubuntu.md","filePath":"[post].md"}'),a={name:"201401/Move Dropbox’s Folder To An External Drive In Ubuntu.md"};function d(x,t,g,w,m,D){const n=i("Link");return u(),l("div",null,[t[14]||(t[14]=p("h1",{id:"在ubuntu中將dropbox文件夾放移動硬盤上",tabindex:"-1"},[o("在Ubuntu中將Dropbox文件夾放移動硬盤上 "),p("a",{class:"header-anchor",href:"#在ubuntu中將dropbox文件夾放移動硬盤上","aria-label":"Permalink to “在Ubuntu中將Dropbox文件夾放移動硬盤上”"},"​")],-1)),p("p",null,[t[1]||(t[1]=o("幾個星期前，我們展示瞭如何[在Microsoft Windows中移動Dropbox文件夾到一個移動硬盤] ",-1)),e(n,{href:"http://www.liberiangeek.net/2013/11/daily-windows-tips-move-dropbox-folder-to-external-drive/"},{default:r(()=>[...t[0]||(t[0]=[o("1",-1)])]),_:1}),t[2]||(t[2]=o("。該教程獲得一致好評。對於使用Ubuntu操作系統的用户來説同樣適用。",-1))]),t[15]||(t[15]=b(`<p>這個簡短的教程將告訴你如何在Ubuntu下輕鬆地將Dropbox文件夾移動到另一個位置。</p><p>我寫這些教程的原因是，幾個月前我收到了一台全新的只有128GB SSD硬盤的惠普EliteBook筆記本電腦。我愛這台快速且性能良好的電腦。</p><p>它的缺點是，本地存儲太小，無法處理我所有的東西。除了我的本地應用程序和數據，我在我的Dropbox也有幾個GB大小的文件。</p><p>所以，當我同步我的Dropbox帳號並下載它的所有內容，我的HP EliteBook，完全消耗掉整個本地磁盤。</p><p>唯一的解決辦法是，不使用本地存儲磁盤直接將Dropbox文件夾移動到一個外部的移動硬盤上中。</p><p>如果你發現自己也有類似的問題，無論是使用Windows還是Ubuntu，請按照下列步驟，以騰出本地磁盤上的空間。在Ubuntu中開始移動Dropbox文件夾，首先插入外部存儲器。（譯註：本例並非真實的外部移動硬盤，而是在vbox測試環境中測試。）</p><p>插入磁盤後，進入Unity Dash 並搜索Disks。打開它並選擇你希望適用的外部驅動器，點擊 <strong>Tools –&gt; Format</strong></p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/dropboxubuntumissingfolder3.png" alt=""></p><p>下一步，格式化驅動器的文件系統為<strong>NTFS</strong>格式。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/dropboxubuntumissingfolder4.png" alt=""></p><p>格式化之後，選擇 <strong>Tools –&gt; Mount Options</strong></p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/dropboxubuntumissingfolder5.png" alt=""></p><p>然後指定相應的選項，如下圖所示：安裝點（準備將Dropbox的文件夾放到這裏），文件系統類型，以及下面的圖片中的其他選項。保存它時，你就大功告成了。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/dropboxubuntumissingfolder6.png" alt=""></p><p>在此之後，退出Dropbox的服務並在默認位置（/home/用户名/Dropbox）刪除當前的Dropbox文件夾（譯註：在Dropbox完全移動好之前，我不建議你如本文一樣刪除原來的文件夾，而是將文件夾改名，要不萬一出錯呢？）。當您再次啓動Dropbox的服務時，它會提醒你缺少的文件夾。點擊重新鏈接按鈕以指定新的位置（就是你的移動硬盤上的新位置）。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/dropboxubuntumissingfolder.png" alt=""></p><p>當提示選擇安裝類型，選擇‘<strong>Advanced’</strong>並指定位置安裝Dropbox文件夾。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/dropboxubuntumissingfolder1.png" alt=""></p><p>設置完畢後，重新啓動，如果Dropbox的不會提示你缺少文件夾，那麼就成功了。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/dropboxubuntumissingfolder2.png" alt=""></p><p>教程就是這樣！</p><p>如果沒有安裝NTFS-3G，運行這個命令來安裝它。</p><pre><code>sudo apt-get install ntfs-3g
</code></pre><hr>`,24)),p("p",null,[t[4]||(t[4]=o("via: ",-1)),e(n,{href:"http://www.liberiangeek.net/2013/12/move-dropboxs-folder-to-an-external-drive-in-ubuntu/"},{default:r(()=>[...t[3]||(t[3]=[o("http://www.liberiangeek.net/2013/12/move-dropboxs-folder-to-an-external-drive-in-ubuntu/",-1)])]),_:1})]),p("p",null,[t[7]||(t[7]=o("譯者：",-1)),e(n,{href:"https://github.com/yechunxiao19"},{default:r(()=>[...t[5]||(t[5]=[o("烏龍茶",-1)])]),_:1}),t[8]||(t[8]=o(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[6]||(t[6]=[o("wxy",-1)])]),_:1})]),p("p",null,[t[11]||(t[11]=o("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[9]||(t[9]=[o("LCTT",-1)])]),_:1}),t[12]||(t[12]=o(" 原創翻譯，",-1)),e(n,{href:"http://linux.cn/"},{default:r(()=>[...t[10]||(t[10]=[o("Linux中國",-1)])]),_:1}),t[13]||(t[13]=o(" 榮譽推出",-1))])])}const k=s(a,[["render",d]]);export{v as __pageData,k as default};
